INSERT INTO _fleet_sync_status_owed (machine_id,item_id,target_kind,status_route,version,status_kind,status_acceptance,refusal_kind,refusal_code,refusal_failure,refusal_size_field,refusal_digest,refusal_item_id,cancel_outcome,cancel_too_late_at) VALUES (COALESCE(json_extract(?2,'$.value.sender'),json_extract(?2,'$.value.peer')),
 ?1,
 json_extract(?2,'$.kind'),
 ?2 -> '$.value.route',
 CAST(?3 AS INTEGER),
 json_extract(?4,'$.status.kind'),
 CASE WHEN json_type(?4,'$.status.value.acceptance') IS NOT NULL THEN ?4 -> '$.status.value.acceptance' END,
 json_extract(?4,'$.status.value.reason.kind'),
 json_extract(?4,'$.status.value.reason.value.code'),
 json_extract(?4,'$.status.value.reason.value.kind'),
 json_extract(?4,'$.status.value.reason.value.field'),
 CASE WHEN json_extract(?4,'$.status.value.reason.kind')='itemConflict' THEN json_extract(?4,'$.status.value.reason.value.existing') ELSE json_extract(?4,'$.status.value.reason.value.existing.digest') END,
 json_extract(?4,'$.status.value.reason.value.existing.item'),
 json_extract(?4,'$.cancel.kind'),
 json_extract(?4,'$.cancel.value.at')) ON CONFLICT(item_id,target_kind,machine_id,status_route) DO UPDATE SET version=excluded.version,status_kind=excluded.status_kind,status_acceptance=excluded.status_acceptance,refusal_kind=excluded.refusal_kind,refusal_code=excluded.refusal_code,refusal_failure=excluded.refusal_failure,refusal_size_field=excluded.refusal_size_field,refusal_digest=excluded.refusal_digest,refusal_item_id=excluded.refusal_item_id,cancel_outcome=excluded.cancel_outcome,cancel_too_late_at=excluded.cancel_too_late_at,updated_at=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER));
